async function fetchHtml(url){let response=await fetch(url);if(!response.ok)throw new Error(`Failed to fetch ${url}: ${response.status}`);return response.text()}async function loadShell(fragments=[]){let base=new URL(".",import.meta.url),[shellHtml,...fragmentHtmls]=await Promise.all([fetchHtml(new URL("shell.html",base)),...fragments.map(name=>fetchHtml(new URL(`fragments/${name}.html`,base)))]),mount=document.getElementById("mapsShellMount");if(!mount)throw new Error("Shell mount point #mapsShellMount not found in page");mount.outerHTML=shellHtml,fragmentHtmls.forEach((html,i)=>{let template=document.createElement("template");template.innerHTML=html;for(let element of[...template.content.children]){let selector=element.getAttribute("data-shell-target"),target=selector?document.querySelector(selector):null;if(!target)throw new Error(`Shell fragment '${fragments[i]}' targets '${selector}', not found in shell`);element.removeAttribute("data-shell-target"),target.appendChild(element)}})}export{loadShell};
